-- GloboEditor · atualização "artes x pedidos" + conta de demonstração TrigoDeOuro (senha: trigodeouro)
-- Cole tudo no SQL Editor do Supabase e clique em Run. Pode rodar de novo: não duplica.

-- 1) Tabela artes ganha o tipo (arte = visual de 1 sacola · pedido = carrinho salvo ⭐ · feito = pedido finalizado) e a miniatura
alter table public.artes add column if not exists tipo text not null default 'pedido';
alter table public.artes add column if not exists preview text;
do $c$ begin
  alter table public.artes add constraint artes_tipo_chk check (tipo in ('arte','pedido','feito'));
exception when duplicate_object then null; end $c$;
create index if not exists artes_dono_tipo on public.artes (dono, tipo);

-- 2) Usuário de demonstração: 2 artes, 2 pedidos salvos e 3 pedidos já feitos
--    (os feitos cobrem todos os tamanhos e artes salvas -> repetir não cobra clichê novo)
do $do$
declare uid uuid; em text := 'trigodeouro@globoeditor.app';
begin
  select id into uid from auth.users where email = em;
  if uid is null then
    uid := gen_random_uuid();
    insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, email_change, email_change_token_new, recovery_token)
    values ('00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated', em,
      extensions.crypt('trigodeouro', extensions.gen_salt('bf')), now(),
      '{"provider":"email","providers":["email"]}', '{}', now(), now(), '', '', '', '');
    insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    values (gen_random_uuid(), uid, uid::text, jsonb_build_object('sub', uid::text, 'email', em, 'email_verified', true), 'email', now(), now(), now());
  end if;
  delete from public.artes where dono = uid and nome in (
    'Trigo de Ouro — Sacos de pão (feito pelo cliente no site)', 'Trigo de Ouro — Lanches e delivery (feito pelo vendedor, pedido por telefone)',
    'Trigo de Ouro — Clássico vermelho', 'Trigo de Ouro — Delivery (faixas café)',
    'Pedido do mês — sacos de pão (feito pelo cliente no site)', 'Pedido delivery — lanches (feito pelo vendedor, por telefone)',
    'Pedido GL-DEMO01', 'Pedido GL-DEMO02', 'Pedido GL-DEMO03');
  insert into public.artes (dono, tipo, nome, dados, resumo, preview, criado, atualizado) values
